const fs = require('fs');
const path = require('path');
function rot13(str) {
  return str.replace(/[a-zA-Z]/g, function(c) {
    return String.fromCharCode((c <= 'Z' ? 90 : 122) >= (c = c.charCodeAt(0) + 13) ? c : c - 26);
  });
}
function processDir(dir) {
  const files = fs.readdirSync(dir);
  for (const file of files) {
    const fullPath = path.join(dir, file);
    if (fs.statSync(fullPath).isDirectory()) {
      processDir(fullPath);
    } else {
      if (/\.(md|txt|json|js|css|html|yml|yaml|csv|sh|xml|svg)$/i.test(fullPath) || file === 'CNAME') {
        try {
          const content = fs.readFileSync(fullPath, 'utf8');
          fs.writeFileSync(fullPath, rot13(content), 'utf8');
        } catch (e) {
          console.error('Failed on ' + fullPath);
        }
      }
    }
  }
}
processDir('/usr/lib/node_modules/openclaw/docs');
console.log('ROT13 applied to docs files.');
